SELECT p.id, p.street_area_id, sa.name AS street_area_name,
       p.name, p.poi_type, p.status
FROM poi p
JOIN street_area sa ON p.street_area_id = sa.id


        AND p.street_area_id = #{query.streetAreaId}


        AND p.poi_type = #{query.poiType}


        AND p.status = #{query.status}


ORDER BY p.id DESC
LIMIT #{page.offset}, #{page.size}

SELECT COUNT(*) FROM poi p


        AND p.street_area_id = #{query.streetAreaId}


        AND p.poi_type = #{query.poiType}


        AND p.status = #{query.status}
